   339    enum Coverage
   340    {
   341      Vertical            = 0x80000000,   /* Set if table has vertical kerning values. */
   342      CrossStream         = 0x40000000,   /* Set if table has cross-stream kerning values. */
   343      Variation           = 0x20000000,   /* Set if table has variation kerning values. */
   344      Backwards           = 0x10000000,   /* If clear, process the glyphs forwards, that
   345                                           * is, from first to last in the glyph stream.
   346                                           * If we, process them from last to first.
   347                                           * This flag only applies to state-table based
   348                                           * 'kerx' subtables (types 1 and 4). */
   349      Reserved            = 0x0FFFFF00,   /* Reserved, set to zero. */
   350      SubtableType        = 0x000000FF,   /* Subtable type. */
   351    };
