   353    template <typename context_t>
   354    inline typename context_t::return_t dispatch (context_t *c) const
   355    {
   356      unsigned int subtable_type = get_type ();
   357      TRACE_DISPATCH (this, subtable_type);
   358      switch (subtable_type) {
   359      case 0      :               return_trace (c->dispatch (u.format0));
   360      case 1      :               return_trace (c->dispatch (u.format1));
   361      case 2      :               return_trace (c->dispatch (u.format2));
   362      case 4      :               return_trace (c->dispatch (u.format4));
   363      case 6      :               return_trace (c->dispatch (u.format6));
   364      default:                    return_trace (c->default_return_value ());
   365      }
   366    }
